from collections import deque
import numpy as np

def find_clusters(grid, start, goal):
    # Define action set and their corresponding changes in coordinates
    actions = {"up":[-1, 0], "down":[1, 0], "left":[0,-1], "right":[0,1]}

    # Create a queue for BFS and add the starting state
    queue = deque([[start]])

    # Create a set to store visited states
    visited = set([start])

    # Create a dictionary to store clusters
    clusters = {}

    while queue:
        path = queue.popleft()
        node = path[-1]

        # If the current state is the goal, stop exploring from this branch
        if node == goal:
            continue

        # Get all neighbors of the current state
        neighbors = get_neighbors(grid, node, actions)

        for neighbor in neighbors:
            if neighbor not in visited:
                visited.add(neighbor)

                # Create a new path by appending the neighbor to the current path
                new_path = list(path)
                new_path.append(neighbor)

                queue.append(new_path)

                # Group states based on their optimal actions and expected value from following the policy
                cluster_id, _ = find_cluster(grid, node, neighbor, visited, actions)

                if cluster_id not in clusters:
                    clusters[cluster_id] = []

                clusters[cluster_id].append(neighbor)

    return clusters

def get_neighbors(grid, state, actions):
    x, y = state // len(grid[0]), state % len(grid[0])
    neighbors = []

    for action, (dx, dy) in actions.items():
        nx, ny = x + dx, y + dy

        if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] != 'X':
            neighbors.append(nx * len(grid[0]) + ny)

    return neighbors

def find_cluster(grid, state1, state2, visited, actions):
    # Calculate distance to the goal
    def dist_to_goal(state):
        x, y = state // len(grid[0]), state % len(grid[0])
        return abs(x - grid.index([cell for row in grid if cell == 7][0])) + abs(y - [row.index(7) for row in grid if 7 in row][0])

    # Calculate the expected value from following the policy
    def expected_value(state):
        return sum([1.0 / len(get_neighbors(grid, state, actions)) * dist_to_goal(nbr) for nbr in get_neighbors(grid, state, actions)])

    cluster_id = hash(tuple(sorted([(dist_to_goal(state1), expected_value(state1)), (dist_to_goal(state2), expected_value(state2))])))

    return cluster_id, {state1: "State 1", state2: "State 2"}

