from collections import deque

def cluster_states(grid):
    # Initialize a set to keep track of visited states
    visited = set()

    # Define the actions and their corresponding movements
    actions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Function to perform BFS and find all connected states
    def bfs(state):
        queue = deque([(state, [])])
        visited.add(state)

        while queue:
            current_state, path = queue.popleft()

            if current_state == 7:  # Goal state reached, return the path
                return path

            for action in actions:
                new_state = (current_state[0] + action[0], current_state[1] + action[1])

                if (0 <= new_state[0] < len(grid) and 
                    0 <= new_state[1] < len(grid[0]) and 
                    grid[new_state[0]][new_state[1]] != "X" and 
                    new_state not in visited):

                    queue.append((new_state, path + [current_state]))
                    visited.add(new_state)

        # If no path to the goal is found, return an empty list
        return []

    # Perform BFS from each state to find all connected states
    clusters = {}
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if (i, j) not in visited:
                cluster = bfs((i, j))
                clusters[(i, j)] = cluster

    # Define the rotation and reflection operations
    def rotate(state):
        return (len(grid) - state[0] - 1, len(grid[0]) // 2 + state[1])

    def reflect(state):
        return (state[0], len(grid[0]) - state[1] - 1)

    # Group states into abstract states based on rotation and reflection
    abstract_states = {}
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if (i, j) != 7:  # Exclude the goal state

                key = tuple(sorted([(rotate(state), rotate(reflect(state))) for state in clusters[(i, j)]]))

                if key not in abstract_states:
                    abstract_states[key] = []

                abstract_states[key].append((i, j))

    return list(abstract_states.values())

